function singleRowWords(words: string[]): string[] {
  const rows = ["qwertyuiop", "asdfghjkl", "zxcvbnm"].map(r => new Set(r));
  return words.filter(w => {
    const lower = w.toLowerCase();
    return rows.some(set => [...lower].every(c => set.has(c)));
  });
}

