function singleRowWords(words: string[]): string[] {
  const row: Record<string, number> = {};
  ["qwertyuiop", "asdfghjkl", "zxcvbnm"].forEach((r, i) => { for (const c of r) row[c] = i; });
  const out: string[] = [];
  for (const w of words) {
    const lower = w.toLowerCase();
    const r = row[lower[0]];
    let ok = true;
    for (const c of lower) if (row[c] !== r) { ok = false; break; }
    if (ok) out.push(w);
  }
  return out;
}

